// C# async is a compiler-generated coroutine (a state machine of awaiters).
public async Task<Result> HandleAsync(int id)
{
    var user   = await _client.GetAsync(id).ConfigureAwait(false);  // no context capture
    var orders = await _orders.FetchAsync(user).ConfigureAwait(false);
    return new Result(user, orders);
    // try/catch/return all work across the whole sequence, unlike a callback chain.
}

// ValueTask<T>: the allocation-free path when the result is usually synchronous
